package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Real;
    in attribute io_1 : Real;
    in attribute io_2 : Real;
    in attribute io_6 : Boolean;
    attribute previousPressed : Boolean := false;
    attribute autoManual : Boolean := false;
    attribute pumpRunningManual : Boolean := false;
    attribute manualPumpElapsedMs : Integer := 0;
    perform action tick {
      first start;
      then if ((io_6) and ((not previousPressed))) {
        first start;
        then assign autoManual := (not autoManual);
      }
      then if ((((io_6) and ((not previousPressed)))) and ((not autoManual))) {
        first start;
        then assign pumpRunningManual := true;
        then assign manualPumpElapsedMs := 0;
      }
      then if pumpRunningManual {
        first start;
        then assign manualPumpElapsedMs := manualPumpElapsedMs;
        then if manualPumpElapsedMs >= 5000 {
          first start;
          then assign pumpRunningManual := false;
        }
      }
      then assign previousPressed := io_6;
    }
    out attribute io_3 : Boolean = (if autoManual ? io_3 else (if pumpRunningManual ? true else false));
    out attribute io_4 : Boolean = autoManual;
    out attribute io_5 : Integer = 0;
    out attribute io_7 : Integer = 0;
    out attribute serial_0_trigger : Boolean = true;
    out attribute serial_0_value_0 : Real = io_0;
    out attribute serial_0_value_1 : Real = io_1;
    out attribute serial_0_value_2 : Real = io_2;
    out attribute serial_0_value_3 : Boolean = autoManual;
    out attribute serial_0_value_4 : Boolean = false;
  }
  part system : Controller;
}

